<script setup>
import { nextTick, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { chatWithIndustrialAI } from '@/industrialAI'
import { conversations, initialMessages, quickQuestions } from '@/mock/chat'

const messages=ref(initialMessages.map(i=>({...i}))); const input=ref(''); const loading=ref(false); const chatBody=ref(); const activeConversation=ref(1)
function scrollBottom(){nextTick(()=>{if(chatBody.value)chatBody.value.scrollTop=chatBody.value.scrollHeight})}
async function sendMessage(text=input.value){const content=text.trim();if(!content||loading.value)return;messages.value.push({id:Date.now(),role:'user',time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),content});input.value='';loading.value=true;scrollBottom();try{const reply=await chatWithIndustrialAI(content);messages.value.push({...reply,id:Date.now()+1,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})})}finally{loading.value=false;scrollBottom()}}
function newChat(){messages.value=initialMessages.map(i=>({...i,id:Date.now()}));activeConversation.value=0;ElMessage.success('已创建新会话')}
</script>
<template><div class="chat-page"><section class="page-header"><div><p>INDUSTRIAL FOUNDATION MODEL ASSISTANT</p><h2>工业大模型助手</h2></div><div class="model"><i></i><b>工业基座大模型 · 智能分析演示</b><span>智能分析演示</span></div></section><section class="chat-shell"><aside><el-button type="primary" class="new-chat" @click="newChat"><el-icon><Plus/></el-icon>新建工业会话</el-button><h4>最近会话</h4><button v-for="item in conversations" :key="item.id" :class="{active:activeConversation===item.id}" @click="activeConversation=item.id"><el-icon><ChatLineRound/></el-icon><span><b>{{item.title}}</b><small>{{item.time}}</small></span></button><div class="data-source"><h4>工业仿真数据</h4><span><i></i>生产模拟数据</span><span><i></i>设备模拟数据</span><span><i></i>质量模拟数据</span><span><i></i>工业本体知识</span></div></aside><main><header><div class="bot-avatar"><el-icon><Cpu/></el-icon></div><div><h3>厚板工业智能助手</h3><span><i></i>智能分析演示 · 知识增强模式</span></div><el-tag type="primary" effect="plain">模拟批次 PL-20260810-027</el-tag></header><div ref="chatBody" class="chat-body"><div v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="avatar"><el-icon><User v-if="message.role==='user'"/><Cpu v-else/></el-icon></div><div class="bubble"><div class="message-head"><b>{{message.role==='user'?'当前用户':'工业大模型助手'}}</b><span>{{message.time}}</span></div><p>{{message.content}}</p><template v-if="message.analysis"><div class="risk"><span>风险判断</span><el-tag :type="message.analysis.risk==='高'?'danger':'warning'" effect="dark">{{message.analysis.risk}}风险</el-tag><em>置信度 {{message.analysis.confidence}}%</em></div><section><h4>知识依据</h4><ol><li v-for="item in message.analysis.knowledgeBasis" :key="item">{{item}}</li></ol></section><section><h4>优化建议</h4><ul><li v-for="item in message.analysis.suggestions" :key="item"><el-icon><CircleCheck/></el-icon>{{item}}</li></ul></section><footer><button @click="ElMessage.success('分析结果已保存至决策记录')"><el-icon><DocumentAdd/></el-icon>保存分析</button><button @click="ElMessage.info('已转入智能决策模块')"><el-icon><Right/></el-icon>转为决策</button></footer></template></div></div><div v-if="loading" class="message assistant"><div class="avatar"><el-icon><Cpu/></el-icon></div><div class="bubble typing"><i></i><i></i><i></i><span>正在检索工业本体与模拟数据</span></div></div></div><div class="composer"><div class="quick"><span>固定演示问题</span><button v-for="item in quickQuestions" :key="item" @click="sendMessage(item)">{{item}}</button></div><div class="input-box"><el-input v-model="input" type="textarea" :rows="2" resize="none" maxlength="500" placeholder="请输入生产、设备或质量问题，Enter 发送，Shift+Enter 换行" @keydown.enter.exact.prevent="sendMessage()"/><el-button type="primary" :loading="loading" @click="sendMessage()"><el-icon><Promotion/></el-icon>发送</el-button></div><p>前端规则模拟 · 未接入真实模型 API</p></div></main></section></div></template>
